def norm(m):
    return m.replace('-', ':').upper()

def allowed(mac, whitelist):
    return norm(mac) in [norm(w) for w in whitelist]

def filter_devices(macs, whitelist):
    return [m for m in macs if allowed(m, whitelist)]

def decide(rules, ip, port):
    for action, rip, rport in rules:
        if (rip == '*' or rip == ip) and (rport == '*' or rport == port):
            return action
    return 'block'
